CREATE OR REPLACE FUNCTION public.guard_relay_club_change() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE current_club uuid; BEGIN IF TG_TABLE_NAME='athletes' THEN SELECT club_id INTO current_club FROM public.athletes WHERE id=NEW.id; IF EXISTS(SELECT 1 FROM public.relay_entries r WHERE NEW.id=ANY(ARRAY[r.swimmer_1_id,r.swimmer_2_id,r.swimmer_3_id,r.swimmer_4_id,r.alt_1_id,r.alt_2_id]) AND r.club_id IS DISTINCT FROM current_club) THEN RAISE EXCEPTION 'Retira al atleta de los relevos antes de cambiar de club'; END IF; RETURN NEW; ELSE IF EXISTS(SELECT 1 FROM public.relay_entries WHERE club_id=OLD.club_id AND meet_id=OLD.meet_id) THEN RAISE EXCEPTION 'No puedes retirar una competencia con relevos'; END IF; RETURN OLD; END IF; END $$;
DROP TRIGGER guard_relay_athlete_club ON public.athletes;
CREATE CONSTRAINT TRIGGER guard_relay_athlete_club AFTER UPDATE ON public.athletes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.guard_relay_club_change();